def retry_delays(attempts, base, cap):
    if attempts < 0 or base < 0 or cap < 0:
        raise ValueError('arguments must be non-negative')
    return [min(base * (2 ** i), cap) for i in range(attempts)]

def group_adjacent(items, key):
    groups = []
    for item in items:
        if not groups or key(groups[-1][0]) != key(item):
            groups.append([item])
        else:
            groups[-1].append(item)
    return groups

import re

def parse_duration(value):
    match = re.fullmatch(r'(0|[1-9][0-9]*)(ms|s)', value)
    if not match:
        raise ValueError('invalid duration')
    amount = int(match.group(1))
    return amount * (1000 if match.group(2) == 's' else 1)

def merge_sorted(a, b):
    i = j = 0
    out = []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i]); i += 1
        else:
            out.append(b[j]); j += 1
    out.extend(a[i:])
    out.extend(b[j:])
    return out

from concurrent.futures import ThreadPoolExecutor

def bounded_map(function, items, limit):
    if limit < 1:
        raise ValueError('limit must be positive')
    with ThreadPoolExecutor(max_workers=limit) as executor:
        return list(executor.map(function, items))

from pathlib import PurePosixPath

def is_safe_relative_path(value):
    if not isinstance(value, str) or not value or '\\' in value:
        return False
    path = PurePosixPath(value)
    return not path.is_absolute() and value != '.' and all(part not in ('', '.', '..') for part in value.split('/'))
